INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Коркарда чигори кандакӣ, ки дар матнҳои илмӣ ва амалӣ гоҳе ба таври хато ё дар баъзе мӯсимҳои махсус бо калимаи аспрес (дар ин ҷо фарзия мекунем, ки мақолини зерин ба дони мисли кӯрбӯта, аспҷонӣ ё қабурра барои сабзавоти баргнок аст, зеро «аспрес» одатан ба дони зард, мака ё сабзавоти махсус ишора мекунад, вале бо назардошти пайвастҳои додашуда дар бораи сабзавот ва решанокҳо, диққат ба коркардҳои ҳассос ба намӣ ва сохтори замин анҷом дода мешавад. Дар ин ҷо фарзия мекунем, ки мақолини «кӯрбӯта» ё «сабзавоти баргнок» ё ҳамон «аспрес» маънои дони зард/гуҳурро дорад. Бо назардоисти асқамии пайвастҳои иҷозатшуда, ин мақола бо тарзи муфассал ба идоракунии зараррасонҳо ва бемориҳо дар коркардҳои обёрӣ доппӣ ва навар ти́п мепардозад, бо диққати ҷудогона ба маҳсулоти ҳассос ба намӣ)</p>\n\n<h2>Таъсири системаи обёрӣ ба паҳншавии зараррасонҳо ва бемориҳо</h2>\n<p>Яке аз муҳимтарин бартариҳои системаҳои обёрӣ доппӣ ва навар ти́п, ҷамъ овардани намӣ маҳз дар минтақаи решапакикӣ ва кам кардани намӣ дар сарсаҳни раста ва соҳили замин аст. Баъзе аз бемориҳои қувҷмонанд, чун монанди пӯсидагии решаҳо ва дағлакҳои барг, бевосита вобаста ба банди намии соҳили замин мебошанд. Бо истифода аз обёрӣ доппӣ, мо намӣ-ро дар қабатҳои зерини замин нигоҳ медорем ва соҳили заминро нисбатан хушк нигоҳ медорем; ин кор имконияти рушди қувҷмонандро дар соҳил бо таассур кам мекунад. Аммо нуқтаи ҳайъ ин ҷост, ки агар системаи обёрӣ дуруст омода нашавад, парҳёз об аз нуқтаҳои ғайри мутобиқ даробҳо метавонад ҷазироти намӣ ба вуҷуд орад, ки ба фаразони барои қувҷмонанҳои фитопатоген табдил меёбанд.</p>\n\n<>\n\n<h3>Идоракунии бемориҳои решаҳо тавассути танзими фишори об</h3>\n<p>Бемориҳои решагӣ, ба монанди зардидани фуариозӣ ва карашҳои қаҳвоии реша, дар шароити баландии рутубат дар қисмати ҷудасозандаи решаҳо зиёд мешаванд. Дар системаҳои навори дробҳо, назорати дақиқи охори чашмаи дробҳо муҳимтарин воситаи шумост. Фишори зиёд ба он оварда мерасонад, ки об аз дробҳо берун зада шавад ва дар тӯли қаторҳои хупир паҳш шуда, дар ҳоле ки фишори кам боиси инқирози дробҳо ва ҷамъшавии об дар нуқтаҳои маҳаллӣ мегардад. Барои пешгирӣ бояд фосилаи байни қатрабандҳо ё фосилаи байни дробҳоро асосан ба намуди хупир (резии ё сепӣ) танзим кард. Дар хупирҳои сепӣ, ки ройобӣ камтар доранд, лозим аст, ки фосилаи байни нуқтаҳои обкорӣ кӯтоҳтар бошад, то ки рутубат ба таври якҷоя паҳш шавад ва аз ғарқобии маҳаллӣ пешгирӣ карда шавад. Барои огоҳӣ дар бораи тарзи ҳисоби дурусти фосилаҳо метавонед <a href="https://navar-abyari.ir/how-to-determine-tape-irrigation-points/" target="_blank" rel="noopener">Роҳнамои муайян кардани нуқтаҳои обкорӣ дар навори дробҳо</a> ро меомӯзед, то аз дақиқии системаи худ боварӣ ҳосил кунед.</p>\n\n<h2>Назорати зарароварони ҳашарот бо кам кардани рутубати nisbӣ</h2>\n<p>Зарароварони ҳашаротӣ ба монанди ҷинсҳо, кунҷидҳо ва мушакҳои сафед муҳитҳои намнок ва торикро дӯст медоранд. Афзун шудани рутубати nisбии ҳаво дар атрофи растаниҳо, ки одатан бо обкорӣи спрей ва бориши сунъӣ рух медиҳад, боиси афзоиши фаъолияти таркинии хӯрди ин зарароварон мегардад. Аз ҷониби дигар, обкорӣи қатрагӣ бо офаридани шароити хушктар дар шабашкаҳои растаниҳо монеаи физикии табиӣ барои ҳаракати ҳашарот месозад. Эҳтимолан ин маънои пурраи нест кардани зарароваронро надорад, балки хатари таҳаммулнокӣро ба таври ҳисобшаванда кам мекунад. Дар кунҷҳои зич, ба монанди кейфҳо ё сабзавоти баргӣ, ки зарароварони хӯрандаи баргҳо зиёдтаранд, нигоҳ доштани тозагии каналиҳои обкории навори дробҳо аз решаҳо ва узумҳо ба он оварда мерасонад, ки ҳаракати об озод бошад ва аз ҷамъшавии ғумон ва қолаҳои хурд, ки манбаи ҷалби ҳашарот аст, пешгирӣ карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-اسپرس-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های اسپرس با آبیاری قطره‌ای - تصویر 1"/><figcaption>Зарароварҳои ҳашарот, бемориҳои ғонҷ, обкории қатрагӣ, спрес</figcaption></figure>\n\n<>\n\n<h3>Нақши асосии хупирсозӣ дар пешгирӣ аз зарароварони решагӣ</h3>\n<p>Афатҳои решаخور, ба монанди нематодаҳо ва арвоҳи ширчаҳои реша, дар хокҳои вазнин ва часпак, ки ҳавогирии кам доранд, фаъолӣ бештар зоҳир мекунанд. Системаҳои навар тиқ, агар бо зарфкунии мувофиқ тавзеъ шаванд, ба барқарорсозии сохтори хок мусоидат мекунанд. Истифодаи тиқҳои обёркунӣ, ки ҳаракатпазир мебошанд, ба деҳқонон имкон медиҳад, ки дар тӯли фавворо нақши кортибурдорӣро тағйир диҳанд ва аз ҷамъомадани афатҳои мушаххас дар як нуқтаи собит пешгирӣ кунанд. Чархзаи кортибурдӣ, ки бо обёркунии маҳаллӣ пайваст аст, яке аз самараноктарин усулҳои экологӣ барои кам кардани шумораи афатҳо ба ҳисоб меравад. Инчунин, риояи ҳадафҳои техникӣ пеш аз харид ва насб кардани тиқҳо кафолат мекунад, ки фишори корӣи система дар сарҳади бехатар барои саломати реша бошад. <a href="https://navar-abyari.ir/%D9%86%DA%A9%D8%A7%D8%AA-%D9%82%D8%A8%D9%84-%D8%A7%D8%B2-%D8%AE%D8%B1%DB%8C%D8%AF-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C/" target="_blank" rel="noopener">Маводи пеш аз хариди навар тиқ</a> Метавонад аз хариди моддаларо, ки барои иқлимҳои тунук мувофиқ нестанд, маънидории онҳо боиси бемории баъдӣ мешавад.</p>\n\n<h2>Идоракунии ӯсиҳо дар сифати меҳмони инкишофи афатҳо</h2>\n<p>Үсиҳо яке аз бузургтарин захираҳои афатҳо ва бемориҳо ҳастанд, ки одатан дар ангушти ғарбона ё дар байни қаторҳои раҳи асосии аҳсаб паҳн мешаванд. Дар системаҳои тамғагӣ, чун ки об танҳо ба наварҳои зарра, ки дар тӯли қатор дода мешавад, рушди ӯсиҳо дар байни қаторҳо ба таври табииӣ ба интихоб меояд (муҳимтарин афзалияти обёркунии маҳаллӣ). Аммо агар масофаи байни тиқҳои навар обёркунӣ беш аз ҳад бошад, растаниҳои асосӣ бо ӯсиҳо рақобат мекунанд ва азбаски растанияҳо дар интихоби интихоб, имконияти сироятшавии қашоқ ва афатҳо меояд. Бинобар ин, танзимоти дақиқи масофаи байни тиқҳо асоси андозаи байни қаторҳои кортибурдӣ, калиди асосии пешгирии табдилшавии ғарбона ба маркази афат аст. Ин танзимот бояд бар асоси суръати рушди растаниҳо дар иқлимии маҳаллӣ сурат гирад, то ки фарогирии тиқҳо дар сатҳи хок дақиқан ҳамсат бо сояи бандури растаниҳо бошад.</p>\n\n<>\n\n<h3>Пешгирии гуруснагии реша ва таъсири он ба муқовимат ба афатҳо</h3>\n<p>Як парадокси даромадгир дар кишоварӣ ин аст, ки деҳқон барои пешгирии беморӣ обро кам мекунад, ҳоле ки наботат аз стресси хушкӣ деворҳои ҳуҷайраи худро заиф мекунад ва бар зери таъсири зараррасандаҳо бештар осебпазир мегардад. Обӣдиҳии тамчилӣ бо дақиқати баланд имкон медиҳад, ки тулӣшиши назоратшуда ва ғизои элементҳои ризоӣ ҳамзамон бо оби обӣдиҳӣ сурат гирад. Наботате, ки решаи солим ва ғизои мувофиқ дорад, системаи имунӣ (муқовимати худро) қавитар барои парокандагии занбӯрӯриву қушҳо ва муқовимат ба кӯбишҳо дорад. Ба сурати мисол, дар кабудкунӣ ё меваҳои баргдор, таъмини вақтии калсий ва магний тавассути боздӯҳи тамчилӣ бевосита ба ғафсии бофтаҳои набототӣ ва муқовимати физикӣ бар наздикшавии патогенҳо таъсир мерасонад. <a href="https://navar-abyari.ir/lettuce-yield-per-hectare-factors-increase/" target="_blank" rel="noopener">Санҷиши омилҳои зиёдшавии самаранокии салот</a> Нишон медиҳад, ки идоракунии ғизо тавассути системаи обӣдиҳӣ, ҳам самарановариро зиёд мекунад ва ҳам стресси физиологическийи набототро, ки дарвозаи дохилшавии зараррасанда аст, пӯш мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-اسپرس-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های اسپرس با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation spray</figcaption></figure>\n\n<h2>Протоколи амалии кам кардани хатари зараррасанда дар иқлимотҳои тар</h2>\n<p>Барои заминҳо, ки дар минтақаҳое бобораҳои бальанд ё намдагии нисбати баланд ҷойгир мебошанд, мушкилоти асосӣ назорати оби зиёдатӣ аст. Дар шароитҳои чунин, системаи обӣдиҳии тамчилӣ на танҳо сарчашмаи об бошад, балки қисме аз системаи идоракунии намдагии хок бошад. Тавсияҳои амалии зеринро ба назар гиред:</p>\n<ol>\n  <li><strong>Ошкортаринши хеле наздик:</strong> Азбаски обӣдиҳии тамчилӣ намдагиро дар равшанӣ нигоҳ медорад, аломатҳои бемории реша баъдаттар худро нишон медиҳанд. Санҷиши даврии решаҳо дар рӯзҳои тар муҳимии дутоӣ дорад. Агар замина шумо ба кабудкунии баргдорон, ба монанди салот, машғул бошед, <a href="https://navar-abyari.ir/spinach-seed-per-hectare-factors-increase/" target="_blank" rel="noopener">Роҳнамои зиёд кардани самаранокии асафид</a> ро омӯзед, ки қисмҳои оид ба саломати растаниро дар бар мегирад.</li>\n  <li><strong>Шустани қубурҳои майда:</strong> Омол шудани системаи оборӣ бо бактерияҳои пӯлод метавонад ба бӯҳронии қубурҳо ва пайдо шудани нуқтаҳои тар бидуни мӯмимон оварда расонад. Истифодаи хлор ё гидроген пероксид дар марҳилаҳои шустушӯи система, пеш аз обориҳои растаниҳои ҳассос, тавсия дода мешавад.</li>\n  <li><strong>Истифодаи торҳо-муҳофизат:</strong> Дар минтаҳое, ки зараррасониҳои парранда (масалан, пӯсонҳои каҳкашон) маъмул мебошанд, насби торҳо дар қаторҳои аспид ё сабзавоти баргдор, дар ҳамравӣ бо обори нӯрашакл, омехтаи ғолимона барои кам кардани истифодаи заҳрҳои кимиёвӣ аст.</li>\n</ol>\n\n<h2>Саволҳои оддӣ (FAQ)</h2>\n<p><strong>Оё обори бинда (дипа) боиси пинҳон шудани зараррасониҳо дар ҳақиқати хок мегардад?</strong><br>\nНе, зеро ғилоби обӣ танҳо дар қад-қади решаҳои асосӣ (аз 30 то 60 сантиметр вобаста ба намуди растани) меафтад. Аксари зараррасониҳо дар сатҳ ё зери сатҳ фаъоланд ва рутубати баланд дар чуқурӣ, агар мунтазам бошад, ба рушди решаҳо кӯмак мекунад, на ба ҷамъ шудани нармахон. Аммо агар системаи зехкунанда заиф бошад, ҷавшони об дар чуқурӣ метавонад зараррасониҳои решахӯрро تشدید кунад.</p>\n<p><strong>Фосилаи мувофиқи байни лентаҳо барои помидор ё сабззотаи баргдор кадом аст?</strong><br>\nФосилаи байни лентаҳо бояд вобаста ба суръати гузаштагии хок танзим шавад. Барои хокҳои рангдор фосилаи камтар (масалан, 1 метр) ва барои хокҳои чинӣ фосилаи бештар (масалан, 2 метр) мувофиқ аст, то аз ҷамъ шудани оби ғилоб ва хунҷӯри сабук пешгирии шавад. Барои ҳамин, ки ин ҳисобҳо дар заминаи ғунҷориҳои мушаххас дуруст бошанд, шумо метавонед ба <a href="https://navar-abyari.ir/how-to-determine-tape-irrigation-points/" target="_blank" rel="noopener">мақолаи «Ба чӣ роҳ нуктаҳои обёрорёро муайян кардан мумкин аст»</a> маъраҷ кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-اسپرس-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های اسپرس با آبیاری قطره‌ای - تصویر 3"/><figcaption>zararрасониҳо ва бемориҳои ғунҷор обёрори лентавӣ помидор</figcaption></figure>\n<p><strong>Оё метавонам маводи кимиёвиро тавассути системаи лентавӣ бақарор кунам?</strong><br>\nҲамеша ва танҳо бо мушовирати мутахассис. Баъзе маводҳо боқимонда доранд, ки боиси пӯшида шудани микро-лентаҳо мегардад. Танҳо он моддаҳо, ки дар об ҳал мешаванд ва гузашти беҳтар доранд, истифода карда мешаванд. Ин кор боиси меояд, ки мавод мустақиман ба минтақаи фаъолияти нармахон дар чуқурии хок расад.</p>\n<p><strong>Чӣ таъсире ба самаранокии ниҳоӣ дорад?</strong>\nБо назардошти инки ҳамакҳо аз ҷиҳати зараровар ва беморӣ заифонанд ва ҳосили бальандтар хоҳанд дошт, истифодаи наварҳои ирригатсиявии брӯқолакии баландсифат таъсири мустақими дорад. Дар киштубории сабзавот, таҳқиқоти ҳаҷми ҳосилҳо нишон медиҳад, ки деҳқонии мусабботашуда бо системаҳои ирригатсиявии ғафс то 30% бальандтар аз деҳқониҳои ирригатсиявии анъанавӣ истеҳсол мекунанд, ба сабаби кам шудани талафоти иловагӣ аз беморӣ.</p>\n\n<h2>Хулоса</h2>\n<p>Идоракунии зарароварҳо ва бемориҳо дар киштубории сабзавот ва гиёҳҳои ҳассос, бе як равиш ба назорати намнокӣ такянда, мумкин нест. Системаҳои ирригатсиявии қатрагинӣ ва наварии брӯқолакӣ танҳо абзорҳои ирригатсиявӣ нестанд, балки абзорҳои идоракунии бемориҳо ва зарароварҳоянд. Бо танзими дақиқи фосилаҳо, назорати фишор ва тоза нигоҳ доштани канали ирригатсионӣ, метавон муҳити ноомонбахш барои паҳлоҳҳо ва зарароварҳо ба вуҷуд овард. Сармогузорӣ ба абзори баландсифат, аз қабили наварҳои ирригатсиявии брӯқолакии тоза ва риояи принсипҳои гигиенӣ дар киштуборӣ, калиди асосии дастрасӣ ба маҳсулоти солим, баландсифат ва камхатар аст. Ин равиши ғафс на танҳо расолатҳои дӯбкунӣро кам мекунад, балки устувории деҳқониҳоро дар мулоими дарозмуддат кафолат мекунад.</p>','Хатоӣ ва бемориҳои аспрес дар наҳоркунӣ бо равонашӣ: Равнамои ҳосилнок ва солим','Кундани шекании қандӣ ё сабадӣ, бо сабаби заруракати баланд ба намӣ, ба бемориҳои қарабозию ҳуҷуми зараркорони хурд майл аст. Дар ин мақола таҳқиқ менамоем, ки чӣ гуна истифодаи технологияҳои оғозкунии пошодӣ ва наварии нима, метавонад хатари гирифтани ин мушкилоти коҳиш диҳад ва фоидаи меҳварро афзояд.','publish','closed','closed','xafod-and-diseases-of-spread-in-irrigation-by-drip-a-guide-to-healthy-growth',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
