INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Кашти сабзабарги, бахусус ошхӯраи ҳассос ва тоҷида монанд <strong>мешаванд</strong> (Чикоки ё Cichorium intybus) ба эҳтиёти махсус дар идоракунии манбаъҳои об ниёз дорад. Системаҳои обёрӣ тавассути пошиши булғи ва истифода аз лентҳои «тип» яке аз самараноктарин роҳҳоест, ки метавонанд самаранокии истифодаи обро зиёд намуда, сифати маҳсули ниҳоиро беҳтар кунанд. Ин усулҳо тавассути таъмини об монанди булғ дар решаи ошхӯр стрессро аз хушкӣ кам мекунанд ва ба рӯишди баробарпайрави решаҳо кӯмак мерасонанд. Дар ин дастур мо аз марҳилаҳои аввали тайёр кардани замин то ҷамъоварии маҳсулро бо тафсилоти пурра баррасӣ мекунем, то ки кишовунон тавонанд战略и ҷамъбасти барои кашт чикоки бо обёрӣ тавассути пошиши булғро муайян созанд. Аҳамияти ин масъала дар шароити иқлими Эрон, ки аз камбудии манбаъҳои об рӯбарӯем, бештар эҳсос мешавад. Аз ин рӯ, интихоби системаи дурусти обёрӣ на танҳо интихоти техникӣ аст, балки зарурати иқтисодӣ ва экологӣ барои ҳифзи устувории боғзорӣ мебошад.</p>\n\n<h2>Интихоб ва насби лентҳои дурусти обёрӣ барои кашти чикоки</h2>\n<p>Барои муваффақ шудан дар кашти чикоки, интихоби намуди лентаи обёрӣ нақши муҳимро мебозад. Шумо метавонед аз лентҳои дӯхташуда дар паҳлу ё пӯлодии «пост» истифода баред, аммо барои сабзаҳои ҳассоси ба чуқури реша монанд чикоки, лентҳои «пост» бо фосилаи ками чӯмчӯмҳо одданда самаранокии беҳтарро доранд. Фосила байни чӯмчӯмҳо бояд асосан барои фосилаи ҳосилнок гардонишудан муайян шавад. Одатан фосилаи тақрибан аз 10 то 20 сантиметр барои кашти зичи чикоки идеалӣ аст. Фарқи асосӣ байни ин ду намуди лента дар сохтори пайвастҳо ва муқовимати ба фишор аст; лентҳои «пост» одатан умри кории баландтар доранд ва камтар аз сабаби фишори об ва гузашти нурҳои офтоб деформатсия мешаванд. Агар шумо ҷустуҷӯи роҳҳое барои зиёд кардани давомнокӣ ва даври истифодаи ин таҷҳизотро дар назар дошта бошед, омӯзиши дақиқи принсипҳои парвариши лентҳо бисёр муҳим аст. Шумо метавонед тавассути ҷустуҷӯии дастури <a href="https://navar-abyari.ir/mazaya-sharit-al-ray/" title="افزایش عمر کاری نوارهای آبیاری">Дароз кардан дарозии умри кории наворҳои обёрӣ</a> Сарошавҳои амалиро барои кам кардани фаромаши дурнавозҳои худ ёбед. Ин масъала хусусан дар киштзорҳое, ки ба таври муқтаб ва дар фаслҳои гуногуни сол фаъоланд, муҳимтар мешавад. Ҳамчунин, сифати маводе, ки барои сохтани навор истифода мешаванд (масалан, PVC ё PE), таъсири мустақим ба умри фоиданок ва муқовиматашон нисбат ба нурҳои UV дорад.</p>\n<p>Навбати дурусти наворҳо бояд ҳамзамон бо киш нигоҳ дошта шавад. Наворҳоро метавонед мувозии бо сатҳҳо ё дар кунҷ нисбат ба онҳо ҷойгир кунед. Дар мавриди шавод, тавсия мешавад, ки наворҳо дақиқ мувозии бо сатҳҳои кат кунӣ бошанд, то об ба таври якхела дар тӯли сатҳ тақсим шавад. Ҳамчунин, диққат диҳед, ки наворҳо дар хӯрок наҷойгиранд; беҳтар аст онҳоро дар сатҳи хӯрок ё каме дар поён (бо муҳофизат) ҷойгир кунед, то аз хаш ва баста шудан пешгирӣ шавад. Агар дар поён сатҳи хӯрок ҷойгир шаванд, чуқурии дафн набояд аз 15 то 20 сантиметр зиёд шавад, зеро дар чуқурҳои бештар, дастрасӣ барои тозагузорӣ ва шустани дохили навор мушкил мешавад. Як нуқтаи муҳим дигар, шурубистани замин аст; агар замин шуруб дорад, набати наворҳо бояд чунин бошад, ки тақсими якхелаи фишор нигоҳ дошта шавад, то аз ҷамъомадани об дар поёнӣ ва камобӣ дар болоӣ пешгирӣ шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-شوید-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت شوید با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои кат дидан обёрӣ навори ҷадвал шавод</figcaption></figure>\n\n\n<h2>Вақтгузорӣ ва ҷойгиркунии кат дидан (Усулҳои кат дидан) шавод</h2>\n<p>Муайян кардани беҳтарин вақти кат дидани шавод вобастагии мустақим ба намуди иқлим дорад, вале асосҳои умумӣ инҳоянд:</p>\n<ul>\n  <li><strong>Кат дидани баҳорӣ:</strong> Аз авоили то миёнаи баҳор вақти мувофиқ аст, то растаниҳо пеш аз гармии шадиди тобистон ба рушд расанд. Дар ин давра, обёрӣ наворӣ бояд бо шиддати сабук оғоз шавад, то решаҳои тоза ҳарос нашаванд. Ҳамчунин, ҳарорати шабона ва рӯзона бояд назорат шавад, то аз рушди тез растанӣ пеш аз омода шудани решаҳо пешгирӣ шавад.</li>\n  <li><strong>Камкунии тобистонӣ:</strong> Барои минтақаҳое, ки зимистони онҳо мулоим аст, камкунии тобистонӣ имконияти хуб мебошад. Дар ин ҳолат, дар моҳҳои хунуктар миқдори оробиро бояд кам кард, аммо пурраи онро хӯрдан тавсия намешавад. Дар минтақаҳои сард, камкунӣ дар тобистон истифодаи пластикӣ шабкана ё пӯшишро барои ҳифз аз ҳарорат талаб мекунад.</li>\n</ul>\n<p>Бардоштани камкунӣ бо ороии қатрагӣ дақиқӣ дар масофаи сафҳоро талаб мекунад. Одатан, масофаи сафҳо аз 40 то 50 сантиметр ва масофаи ҳунаро дар саф аз 15 то 20 сантиметр барои расидан ба зичии мувофиқ тавсия дода мешавад. Истифодаи бурсҳои яккалӣ ё буруни рӯи баъзан вобаста ба намуди нависонон аст, аммо ҳаргоҳ системаи қатрагӣ бояд фавран фаъол карда шавад, то аз хушк шудани бурсҳо ё буруниҳо пешгирӣ карда шавад. Зичии мувофиқ на танҳо ба афзоиши ҳосилнокии ҳар гектар таъсир мерасонад, балки дар идоракунии зараррасонҳо ва бемориҳо низ нақш меистонад. Зичии зиёд ба рақобат барои рӯшноӣ ва моддаҳои ғизоӣ ва паст шудани сифати рӯшаҳо оварда мерасонад. Бинобар ин, танзими дақиқи масофаи камкунӣ дар асоси қобилияти боркории рӯйпайи нӯрҳои тиб, яке аз муҳимтарин омилҳои муҳандисӣ дар ин раванд аст. Кӯҳсоз бояд пеш аз оғози камкунӣ ҳисоб кунед, ки бо назардошти паҳноии саф ва шумораи қатрагӣ, чанд литр дар соат ба ҳар ниҳол мерасад.</p>\n\n<h3>Барномаи ороӣ (Irrigation Schedule) дар марҳилаҳои афзоиш</h3>\n<p>дар ду марҳилаи асосии афзоиш (марҳилаи рушдӣ ва марҳилаи ҷамъоварии моддаҳо) тааллуқоти гуногун доранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-شوید-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت شوید با آبیاری قطره‌ای - تصویر 2"/><figcaption> усулҳои камкунӣ, фармаи орои қатрагӣ, барномаи ороӣ шавед</figcaption></figure>\n\n<ol>\n  <li><strong>Марҳилаи рушдӣ (4 то 6 ҳафтаро аввалин):</strong> Дар ин марҳила, ниҳол ба об мунтазам ва мулоим ниёз дорад. Орои ҳар 1 то 2 рӯз як маротиба бо миқдори кам (масалан, 2 то 3 литр дар соат барои ҳар қатрагӣ) тавсия дода мешавад. Мақсад, нигоҳдоштани намии рӯшаҳои сатҳӣ аст. Афзоиши тез баҳоронҳо дар ин марҳила ба пайдоиши намии хок ниёз дорад ва камبودҳи ҳатто эҳсосии об метавонад боиси таҳшин шудани баргҳо ва кам шудани ҷабҳиши моддаҳои ғизоӣ гардад.</li>\n  <li><strong>Марҳилаи ҷамъшавии моддаҳо (ҳаҷмгирии реша):</strong> Дар охирин давраи рушд, вақте ки шӯлудар ҳолати ҷамъшавии ширинӣ мебошад, ниёз ба об каме кам мешавад. Обёрӣи мутаносиб (ҳар 3 то 4 рӯз) боиси маъруфии моддаҳои қандӣ дар реша ва зиёд шудани лозими ширинӣ мегардад. Агар об бешвор бошад, решаҳо метавонанд бубурананд ва лозии камтар ширин доранд. Ин марҳила ҳассос аст ва ба назорати дақиқи намудорӣ ниёз дорад, то аз ширинии номаъмул ё заҳалонишудаи реша пешгирӣ карда шавад.</li>\n</ol>\n<p>Ҳамеша пеш аз обёрӣ намуди хокро бо даст ё бо як намудинок санҷед. Обёрӣи қатрагӣ имкон медиҳад, ки бо танзими фишор, бар қуввати қатраҳо идорагӣ кунед. Инчунин, намуди хок (рихӣ, равигӣ, дулоитӣ) ба миқдори намуди нигоҳ дошташуда таъсир мерасонад. Дар хокҳои равигӣ, ки ҷозибиши баланд доранд, шумораи боригии обёрӣ бояд бештар ва миқдори он камтар бошад, то об аз соҳаи реша наравад. Дар хокҳои рихӣ, обёрӣ камтар ва бо ҳаҷми бештар тавсия мешавад. Истифодаи термометрҳои ҳаво ва бумиметр барои назорати ҳарорати хок низ барои танзими дақиқи соатҳои обёрӣ (афзал субҳи зод ё шом) фоидаовар аст.</p>\n\n<h2>Нуқтаҳои амалӣ барои идоракунии обёрӣи қатрагӣ дар боғҳои шӯлуд</h2>\n<p>Бехудкунии системаи обёрӣи қатрагӣ танҳо ба насби нӯриҳо маҳдуд нест, балки идоракунии доимиро низ дар бар мегирад. Дар поён муҳимтарин нуқтаҳои амалиро мурояъ мекунем:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-شوید-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت شوید با آبیاری قطره‌ای - تصویر 3"/><figcaption>usuli neveshtani zakhira va nazorati obboriyi qatragi barои shulod</figcaption></figure>\n\n<ul>\n  <li><strong>Идоракунии бастани нӯриҳо:</strong> Афрӯхтани об бо ҷамъшавии минералӣ ё биологӣ метавонад қатрагарҳо-ро баст кунад. Истифодаи филтери мувофиқ (мисли филтери тобдор ё сангӣ) дар оғози система муҳим аст. Инчунин, шустушуи муқаррабии нӯриҳо тавсия мешавад. Барои фаҳмиши беҳтар чӣ гуна умри кории система зиёд мешавад, мақоларо хонед <a href="https://navar-abyari.ir/mazaya-sharit-al-ray/" title="افزایش عمر کاری نوارهای آبیاری">Ӯмрбоби кори ламелҳои обориро зиёд кардан</a> мӯфид хоҳад буд. Ламелҳоро бояд бо истифода аз хлор ё винилӣ бо консентратсияи паст шуста шавад, то ки зарбаҳои ҷамъшуда ҳал шаванд. Ҳеҷ гоҳ аз моддаҳои шӯюи щеллӣи қавӣ истифода набаред, зеро онҳо ба деворҳои ламел зарар мерасонанд.</li>\n  <li><strong>Нобуд кардани шӯроби зарарранд:</strong> Оборидани таматча бо сабаби оборидани танҳо минтакаи решаҳо ба парҳези шӯроби зарарранд мусоидат мекунад. Аз пӯшидан бо пластик сабук ё кардани зарбаи химиявии шӯроби зарарранд бо дақиқати баланд истифода баред. Барои муқоиса бо методҳои дигари оборидан, метавонед оборидани хусусиеро низ баррасӣ кунед, аммо барои шӯроби зарарранд, таматча самараноктар аст. Пӯшиши набототӣ, ки обро ҷамъ намекунад, ба кам шудани таҳур сатҳӣ ва нигоҳ доштани намнокӣ дар минтакаи решаҳо оварда мерасонад. Интихоби пӯшиши мувофиқ (ранги сиёҳ ё сабз) ба ҳарорати хок ва парҳези шӯроби зарарранди беҳадаф таъсир мекунад.</li>\n  <li><strong>Бақувватии намнокӣ:</strong> Истифодаи сенсорҳои намноки хок ё методҳои дастӣ (мисли санҷиши коса) ба шумо кӯмак мекунад, то барномаи обориданро дақиқтар танзим кунед. Бояд ба тахминҳои умумӣ такя накард; ба ҷои он, дар асоси маълумотҳои хок амал кунед. Насби сенсорҳои ҷонон дар чуқурии 10, 20 ва 30 сантиметр аз сатҳи хок метавонад маълумотҳои дақиқтарро барои контроллерҳои автоматики пардохти об пешниҳод кунад. Ин назорати доимӣ ба пешгирии оборидани иловагӣ ва хориҷшавии энергияи помпа мусоидат мекунад.</li>\n</ul>\n\n<h2>Саволҳои зудбаркардашуда (FAQ) дар бораи оборидани таматча</h2>\n<ol>\n  <li><strong>Оё метавонид аз ламелҳои оборидани умумӣ барои меваҳо ва сабзӣҳои дигар низ истифода баред?</strong><br>Бале, асосҳо монанданд, аммо масофаҳо ва шиддати ороғӣ бояд мувофиқи талаботи авҷани хос танзим шавад. Барои фаҳмиши беҳтари фарқиятҳо, метавонед омӯзишномаҳои дигари парвариш, масалан, миқдори бӯҳни чангиро, хонед, зеро ҳар авҷан талаботи хоси худро дорад. Чангӣ низ ба решаи амиқ ниёз дорад ва системаи қатрагӣ бо масофаи мувофиқи қатраҳо метавонад барои он низ идеалӣ бошад.</li>\n  <li><strong>Беҳтарин масофаи бӯҳн барои дӯшабо бо ороғии қатрагӣ чӣ қадар аст?</strong><br>Масофаи бӯҳнии 15 то 20 сантиметр ва масофаи рақамии 40 то 50 сантиметр одатан беҳтарин мувозинатро байни фазои афзоиши авҷан ва истифодаи об аз нӯри (шарифи) ороғӣ мекунад. Агар хок шағолбошад, метавонад ниёз ба зиёд кардани каме масофаи бӯҳн бошад, то муноzáбат (рақобат)-и решаҳо коҳиш ёбад.</li>\n  <li><strong>Оё имкон дорад, ки пудоро тавассути нӯри қатрагӣ ба дӯшабо расонӣ?</strong><br>Бале, қудронӣ бо усули қатрагӣ (Fertigation) тавассути нӯрҳои (шарифҳои) қатрагӣ хеле самаранок аст. Аз пудороҳое истифода баред, ки хуб ҳал мешаванд ва миқдори паст доранд, то аз сӯзиши решаҳои ҳассос пешгирӣ карда шавад. Ин усул ба ҷузъбаҷузъи тезтари моддаҳои қудрнок ва зиёд кардани натиҷаи ниҳоӣ менамояд, чунон ки дар омӯзишномаи <a href="https://navar-abyari.ir/yield-of-dryland-barley-per-hectare-tips-increase-production/" title="افزایش محصول خشک">Афзоиши маҳсули хушк</a> аксҳои монанди идоракунии ғизо низ зикр шудааст. нақшагирии пудронӣ бояд асосан бар таҳлили хок ва барг иҷро шавад, то аз шустани моддаҳои қудрнок ва армгузорӣ ба обҳои зерзаминӣ пешгирӣ карда шавад.</li>\n</ol>\n\n<h2>Хулоса</h2>\n<p>Истифодаи оварии қатрагӣ ва навои тип дар кӯрпайии чуборошӣ яке аз усулҳои илмӣ ва оптималӣ барои кишоварзии муосир аст. Бо риояи принсипҳои ҷойгиркунӣ, санҷиши дақиқи вақти обӣ дар ҳар марҳилаи рушд ва парвариши мувофиқи таҷҳизот, шудан имконпазир аст, ки ҳарфазои баробари обро ҳифз кард ва маҳсулоти сифатноктари меҳворабарро ба бозор пешниҳод карда шавад. калиди муваффақият, назорати мунтазам ва танзим барномаи обӣ мутобиқи шартҳои иқлимӣ ва маҳаллӣ мебошад. Бо риояи ин дастур, шумо қадами муҳим ба самти кишоварзии доимӣ ва самаранокро паҳлуи майдон гиридаед. Инчунин, шиносӣ бо маҳсулоти дигар, ба монанди <a href="https://navar-abyari.ir/mung-bean-yield-per-hectare-guide/" title="مردمک محصول در هکتار">аспарогус</a> метавонад ҳайчашумо дар идоракунии чархи парвариши кӯрпайии арғамчинӣ ва оптимизатсияи истифодаи замин ва об дар кишоварзии муосир васеъ кунад. Пахшшавии илми оварӣ бо идоракунии дақиқи хок кафолати фоидаоварии дарозмуддати майдонҳои шумо мебошад.</p>\n<p><strong>Мақолаҳои вобаста:</strong> <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%85%D9%88%D8%B3%DB%8C%D8%B1-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Ҳаҷми ҳосилкунии чуборошӣ дар гектар</a>Чистаки оварии дарахтони сабз? Хусусиятҳо ва нуқсонҳо</p>','Комилл руҳсатномаи партобони чорогонӣ бо обёрӣи қатрагон ва техникаи Нова Тейп','Ин мақола ба баррасии анвои мухталифи парвариши сабзотолӯъ бо таваҷҷух ба истифодаи технологияҳои оборӣ бо чандиш ва чизмезоӣ ишора мекунад. Бо ошноӣ бо ин роҳнамо, шумо бо принсипҳои илмӣ ва таҷрибавии ин усули ободӣ, тартиби ғироварӣ, идоракунии сарфи об ва омилҳои таъсиррасон ба ҳосилнокии сабзотолӯъ шинос мешавед. Ҳадафи мо пешниҳоди назари амалӣ мебошад, ки деҳқонон бо камтарин ҳарҷат ва истифодаи захираҳо, боздеҳии бештарро аз майдони сабзотолӯъ худ ба даст оранд. Дар идома, қисмҳои гуногун, аз ҷумла интихоби таҷҳизоти мувофик, нақшарезии ободӣ ва ҷавоб ба саволҳои маъмулӣ муҳокам мегарданд.','publish','closed','closed','ruehsatnoma-chorogoni-obor-qatragon-nova-teyp',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
